"""Convert local STL/STEP/IGES geometry to normalized triangle buffers for render_models.cjs.

Requires Python 3.12, numpy and cadquery-ocp (STEP/IGES only). CAD stays offline.
"""
import argparse
import json
from pathlib import Path
import zipfile
import numpy as np


def triangles(path):
    """Read STL triangles or tessellate every located CAD face, including assemblies."""
    if path.suffix.lower() in ('.stp', '.step', '.igs', '.iges'):
        from OCP.STEPControl import STEPControl_Reader
        from OCP.IGESControl import IGESControl_Reader
        from OCP.IFSelect import IFSelect_RetDone
        from OCP.BRepMesh import BRepMesh_IncrementalMesh
        from OCP.BRep import BRep_Tool
        from OCP.TopAbs import TopAbs_FACE
        from OCP.TopExp import TopExp_Explorer
        from OCP.TopoDS import TopoDS
        from OCP.TopLoc import TopLoc_Location
        reader = IGESControl_Reader() if path.suffix.lower() in ('.igs', '.iges') else STEPControl_Reader()
        if reader.ReadFile(str(path)) != IFSelect_RetDone:
            raise ValueError('Cannot read CAD file')
        reader.TransferRoots()
        shape = reader.OneShape()
        # Fine absolute tessellation; the PNG, rather than geometry, is shipped.
        BRepMesh_IncrementalMesh(shape, 0.05, False, 0.15, True)
        faces = TopExp_Explorer(shape, TopAbs_FACE)
        chunks = []
        while faces.More():
            location = TopLoc_Location()
            mesh = BRep_Tool.Triangulation_s(TopoDS.Face(faces.Current()), location)
            if mesh is not None:
                transform = location.Transformation()
                points = np.array([mesh.Node(i).Transformed(transform).Coord() for i in range(1, mesh.NbNodes() + 1)])
                indices = np.array([mesh.Triangle(i).Get() for i in range(1, mesh.NbTriangles() + 1)]) - 1
                chunks.append(points[indices])
            faces.Next()
        return np.concatenate(chunks)
    if path.suffix.lower() == '.zip':
        with zipfile.ZipFile(path) as archive:
            names = [name for name in archive.namelist() if name.lower().endswith('.stl') and not name.startswith('__MACOSX/')]
            if len(names) != 1:
                raise ValueError('Expected one STL in ZIP')
            data = archive.read(names[0])
    else:
        data = path.read_bytes()
    count = int.from_bytes(data[80:84], 'little')
    if len(data) != 84 + 50 * count:
        raise ValueError('Expected binary STL')
    dtype = np.dtype([('normal', '<f4', 3), ('vertices', '<f4', (3, 3)), ('attribute', '<u2')])
    return np.frombuffer(data, dtype=dtype, offset=84)['vertices'].copy()


def main():
    """Center the native side view and fit the original 88% glass-width framing."""
    parser = argparse.ArgumentParser()
    parser.add_argument('source', type=Path)
    parser.add_argument('output', type=Path)
    parser.add_argument('--alpha', action='store_true', help='Encode renderer alpha bytes as a 16-level indexed PNG')
    parser.add_argument('--compact', action='store_true', help='Encode a source PNG as a compact firmware WebP mask')
    parser.add_argument('--width', type=int, default=1280, help='Compact mask width; height preserves the source aspect ratio')
    parser.add_argument('--levels', type=int, default=16, choices=range(2, 17), help='Compact mask alpha levels; 16 retains the source alpha')
    args = parser.parse_args()
    if args.compact:
        from PIL import Image
        image = Image.open(args.source).convert('RGBA')
        if args.width <= 0 or args.width % 8:
            parser.error('--width must be a positive multiple of eight')
        resized = image.width != args.width
        if resized:
            image = image.resize((args.width, image.height * args.width // image.width), Image.Resampling.LANCZOS)
        # Quantize after resampling so interpolated alpha does not inflate the palette.
        if resized or args.levels != 16:
            pixels = np.array(image)
            alpha = pixels[:, :, 3].astype(float)
            pixels[:, :, 3] = np.rint(np.rint(alpha * (args.levels - 1) / 255) * 255 / (args.levels - 1)).astype('uint8')
            image = Image.fromarray(pixels)
        image.save(args.output, lossless=True, quality=100, method=6)
        return
    if args.alpha:
        from PIL import Image
        image = Image.frombytes('P', (1600, 1000), args.source.read_bytes())
        image.putpalette([255] * 768)
        image.info['transparency'] = bytes(i * 17 for i in range(16))
        image.save(args.output, bits=4, optimize=True)
        return
    vertices = triangles(args.source).reshape(-1, 3)
    lower, upper = vertices.min(axis=0), vertices.max(axis=0)
    print(json.dumps({'bounds': [lower.tolist(), upper.tolist()], 'triangles': len(vertices) // 3}), flush=True)
    vertices = (vertices - (lower + upper) / 2) * (60000 / (upper[0] - lower[0]))
    if np.max(np.abs(vertices)) > 32767:
        raise ValueError('Geometry does not fit the side-view coordinate range')
    args.output.parent.mkdir(parents=True, exist_ok=True)
    np.rint(vertices).astype('<i2').tofile(args.output)


if __name__ == '__main__':
    main()
# AI: end
